    const { row } = locateLastRow({ pr: args.pr, headSha: args["head-sha"] });
    process.stdout.write(JSON.stringify(row) + "\n");
  } catch (e) {
    process.stderr.write(`${e.message}\n`);
    process.exit(1);
  }
}
